{
  "hypothesis": "A short, boundary-focused topology tournament followed by continuation-based packet-weight repair will escape the incumbent structure and gain at least 1e-5.",
  "rationale": "The previous search spent much of its budget on arbitrary cuts and then repaired only one candidate using an immediately sharp maximum approximation. This version prioritizes packet boundaries, preserves several distinct contenders, and allocates repair time by successive halving while gradually sharpening the objective.",
  "source": "import time
import numpy as np
from scipy import fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'total_fraction': (0.70, 0.55, 0.72),
    'search_fraction': (0.20, 0.08, 0.35),
    'packet_width': (1024, 64, 8192),
    'initial_beta': (30000.0, 1000.0, 1000000.0, 'log'),
    'final_beta': (300000000.0, 1000000.0, 10000000000.0, 'log'),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.r_[a[:k][::-1], a[k:]]
    if mode == 2:
        return np.r_[a[:k], a[k:][::-1]]
    return np.r_[a[k:], a[:k]] if k else a


def exact(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.r_[0., c, 0.]
    a, b = y[:-1], y[1:]
    numerator = float(np.sum((np.diff(x)/3)*(a*a+a*b+b*b)))
    return float(numerator / ((np.sum(np.abs(c))/(len(c)+1))*np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    end = start + params['total_fraction']*budget_s
    search_end = start + params['search_fraction']*budget_s
    if init is None:
        return {'values': [1.]}
    f = decode(init)
    best_score = exact(f)
    best = None
    n = len(f)
    if n < 4 or time.monotonic() >= end-2:
        return init
    f = f/f.max()
    m = fft.next_fast_len(2*n-1, real=True)
    rng = np.random.default_rng(seed)

    def convolution(a):
        sp = fft.rfft(a, m)
        return fft.irfft(sp*sp, m)[:2*n-1]

    def metric(c):
        return float((2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/(3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def retain(a, score):
        nonlocal best, best_score
        if score > best_score + 5e-14 and time.monotonic() < end-1.5:
            s = exact(a)
            if s > best_score:
                best_score, best = s, a.copy()

    active = f > f.max()*1e-12
    edges = np.flatnonzero(active[1:] != active[:-1])+1
    boundaries = np.r_[0, edges, n]
    widths = np.diff(boundaries)
    jobs = []
    # Short end reflections preserve most of the existing pair-sum structure.
    for d in np.geomspace(2, max(3, n//3), 20):
        if time.monotonic() >= search_end:
            break
        k = int(d)
        if len(edges):
            near = edges[np.argmin(np.abs(edges-k))]
            far = edges[np.argmin(np.abs(edges-(n-k)))]
            jobs.extend([(int(near), 1), (int(far), 2)])
        jobs.extend([(k, 1), (n-k, 2)])
    # Large empty intervals are natural seams for cyclic changes.
    for j in np.argsort(widths)[::-1][:20]:
        if time.monotonic() >= search_end:
            break
        if not active[boundaries[j]]:
            for k in (boundaries[j], boundaries[j+1], (boundaries[j]+boundaries[j+1])//2):
                jobs.append((int(k), 0))
    # Mix scales rather than consuming all trials on one kind of move.
    rng.shuffle(jobs)
    pool = []
    seen = set()
    mode_best = {}
    for k, mode in jobs:
        if time.monotonic() >= search_end:
            break
        if not 0 < k < n or (k, mode) in seen:
            continue
        seen.add((k, mode))
        if mode == 0:
            a = np.r_[f[k:], f[:k]]
        elif mode == 1:
            a = np.r_[f[:k][::-1], f[k:]]
        else:
            a = np.r_[f[:k], f[k:][::-1]]
        difference = np.sum(np.abs(a-f))/np.sum(f)
        if difference < 1e-9:
            continue
        c = convolution(a)
        s = metric(c)
        retain(a, s)
        if mode not in mode_best or s > mode_best[mode][0]:
            mode_best[mode] = (s, a)
    pool = sorted(mode_best.values(), key=lambda v: v[0], reverse=True)[:2]
    if not pool:
        pool = [(best_score, f)]
    # Use a feasible fallback if all structural changes are catastrophically bad.
    if pool[0][0] < best_score-0.015:
        pool = [(best_score, f)]

    class Stop(Exception):
        pass

    def prepare(a, score):
        c = convolution(a)
        base = a/np.sqrt(max(c.max(), 1e-300))
        ix = np.flatnonzero(base > 0)
        split = np.r_[True, (np.diff(ix) != 1) | (ix[1:]//int(params['packet_width']) != ix[:-1]//int(params['packet_width']))]
        labels = np.cumsum(split, dtype=np.int64)-1
        return {'base': base[ix], 'ix': ix, 'labels': labels, 'x': np.zeros(int(labels[-1])+1), 'score': score}

    states = []
    for s, a in pool:
        if time.monotonic() >= end-2:
            break
        states.append(prepare(a, s))
    if not states:
        return init if best is None else {'values': best.tolist()}

    def repair(state, beta, until):
        ix, labels, base = state['ix'], state['labels'], state['base']
        groups = len(state['x'])
        latest = [state['x'].copy()]
        def objective(x):
            if time.monotonic() >= min(until, end-1.7):
                raise Stop()
            latest[0] = x.copy()
            weights = np.exp(np.clip(x, -25, 25))
            a = np.zeros(n)
            a[ix] = base*weights[labels]
            sp = fft.rfft(a, m)
            c = fft.irfft(sp*sp, m)[:2*n-1]
            score = metric(c)
            state['score'] = max(state['score'], score)
            retain(a, score)
            peak = c.max()
            # The smoothing scale follows amplitude, avoiding scale drift.
            tau = max(peak/beta, 1e-300)
            e = np.exp((c-peak)/tau)
            z = e.sum()
            smooth = peak+tau*np.log(z)
            num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
            total = a.sum()
            g = 4*c
            g[1:] += c[:-1]
            g[:-1] += c[1:]
            g /= 3*num
            g -= e/(z*smooth)
            corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
            grad = np.bincount(labels, weights=(2*corr[ix]-2/total)*a[ix], minlength=groups)
            value = np.log(num)-2*np.log(total)-np.log(smooth)
            return -float(value), -grad
        try:
            result = minimize(objective, state['x'], jac=True, method='L-BFGS-B', bounds=[(-8.,8.)]*groups,
                              options={'maxiter': 1000, 'maxfun': 2000, 'maxls': 8, 'maxcor': 5, 'ftol': 0., 'gtol': 0.})
            state['x'] = result.x
        except Stop:
            state['x'] = latest[0]

    # Successive halving: modest smoothing screens topologies, then all remaining
    # time goes to the best repaired branch with a substantially sharper maximum.
    remaining = max(0., end-time.monotonic()-2.)
    screening_end = time.monotonic()+0.42*remaining
    for j, state in enumerate(states):
        if time.monotonic() >= screening_end:
            break
        allocation = (screening_end-time.monotonic())/(len(states)-j)
        repair(state, float(params['initial_beta']), time.monotonic()+allocation)
    states.sort(key=lambda state: state['score'], reverse=True)
    for beta in (np.sqrt(params['initial_beta']*params['final_beta']), params['final_beta']):
        if time.monotonic() >= end-2:
            break
        remaining = end-1.8-time.monotonic()
        fraction = 0.42 if beta != params['final_beta'] else 1.0
        repair(states[0], float(beta), time.monotonic()+fraction*remaining)
    if best is None:
        return init
    return {'ring': best.tolist(), 'cut': 0, 'reflection': 0}
